from __future__ import annotations

from pathlib import Path
from typing import Any

import pandas as pd

try:
    from docx import Document
    from docx.enum.text import WD_ALIGN_PARAGRAPH
    from docx.oxml import OxmlElement
    from docx.oxml.ns import qn
    from docx.shared import Inches, Pt, RGBColor
except ImportError:  # pragma: no cover - depends on local optional dependency.
    Document = None


DISCLAIMER = (
    "This report is generated by an AI-assisted tool for QA/RA review only. "
    "It is not a final approved controlled document. All regulatory interpretations "
    "and document amendments must be reviewed and approved according to the company "
    "document-control procedure before implementation."
)


def generate_report(
    output_path: str | Path,
    excel_info: dict[str, Any],
    folder_info: dict[str, Any],
    affected_df: pd.DataFrame,
    review_items: list[dict[str, Any]],
) -> Path:
    if Document is None:
        raise RuntimeError("python-docx is not installed. Install dependencies before generating amendment_report.docx.")

    path = Path(output_path)
    path.parent.mkdir(parents=True, exist_ok=True)
    doc = Document()
    doc.add_heading("AI-Assisted Regulatory Update Impact Assessment and Draft Amendment Report", 0)
    doc.add_paragraph("AI辅助法规更新影响评估及文件修订建议报告")

    doc.add_heading("1. Summary / 摘要", level=1)
    doc.add_paragraph(f"Affected rows / 受影响记录数: {len(affected_df)}")
    doc.add_paragraph("All outputs are draft suggestions for QA/RA review only. 所有输出仅供QA/RA审核。")

    doc.add_heading("2. Uploaded Regulation Excel Information / 法规Excel信息", level=1)
    for key, value in excel_info.items():
        doc.add_paragraph(f"{key}: {value}")

    doc.add_heading("3. Controlled-Document Folder Information / 受控文件夹信息", level=1)
    for key, value in folder_info.items():
        doc.add_paragraph(f"{key}: {value}")

    doc.add_heading("4. Updated Regulations Reviewed / 已审核法规更新", level=1)
    for _, row in affected_df[["regulation_old", "regulation_latest", "status", "latest_year"]].drop_duplicates().head(200).iterrows():
        doc.add_paragraph(
            f"{row.get('regulation_old')} -> {row.get('regulation_latest')} | "
            f"{row.get('status')} | {row.get('latest_year')}"
        )

    doc.add_heading("5. Affected Documents / 受影响文件", level=1)
    affected_columns = [
        column
        for column in [
            "document_code",
            "document_title",
            "document_type",
            "affected_file",
            "candidate_level",
            "candidate_reason",
            "relationship_path",
            "reference_evidence",
        ]
        if column in affected_df.columns
    ]
    for _, row in affected_df[affected_columns].drop_duplicates().head(300).iterrows():
        doc.add_paragraph(
            f"{row.get('document_code')} | {row.get('document_type')} | "
            f"{row.get('affected_file')} | {row.get('candidate_level', '')} | "
            f"{row.get('candidate_reason', '')} | {row.get('relationship_path', '')} | "
            f"{row.get('reference_evidence', '')}"
        )

    doc.add_heading("6. Detailed Amendment Suggestions / 详细修订建议", level=1)
    for item in review_items:
        _add_review_item(doc, item)

    doc.add_heading("7. Items Requiring Regulatory Confirmation / 需要法规确认事项", level=1)
    confirm = affected_df[affected_df.get("ai_decision", affected_df.get("priority", "")) == "Need confirmation"] if not affected_df.empty else affected_df
    for _, row in confirm.head(200).iterrows():
        doc.add_paragraph(f"{row.get('document_code')} | {row.get('regulation_old')} | {row.get('reason')}")

    doc.add_heading("8. Reviewer Approval Checklist / 审核清单", level=1)
    for text in [
        "QA/RA reviewer confirmed regulatory source. QA/RA审核员已确认法规来源。",
        "Affected controlled-document sections reviewed. 已审核受影响受控文件章节。",
        "Final controlled-document change follows document-control procedure. 最终文件变更按文件控制程序执行。",
    ]:
        doc.add_paragraph(f"[ ] {text}")

    doc.add_heading("9. Disclaimer / 免责声明", level=1)
    doc.add_paragraph(DISCLAIMER)
    doc.save(path)
    return path


def _add_review_item(doc: Document, item: dict[str, Any]) -> None:
    doc.add_heading(str(item.get("document_code", "Affected item")), level=2)
    fields = [
        ("Document title / 文件标题", item.get("document_title")),
        ("Document type / 文件类型", item.get("document_type")),
        ("Affected regulation / 受影响法规", item.get("old_standard")),
        ("Old version / 原版本", item.get("old_year")),
        ("Latest version / 最新版本", item.get("latest_standard")),
        ("Latest year / 最新年份", item.get("latest_year")),
        ("Update status / 更新状态", item.get("status")),
        ("Main change summary / 主要变更", item.get("change_summary")),
        ("Document summary / 文件摘要", item.get("document_summary")),
        ("Proposed amendment locations / 建议修订位置", item.get("recommended_amendment_locations") or item.get("proposed_amendment_locations")),
        ("AI suggested English revision / 英文建议", item.get("suggested_revised_english")),
        ("AI suggested Chinese revision / 中文建议", item.get("suggested_revised_chinese")),
        ("Reason / 原因", item.get("reason")),
        ("Risk level / 风险等级", item.get("risk_level")),
        ("Reviewer decision / 审核决定", item.get("reviewer_decision")),
        ("Reviewer comment / 审核意见", item.get("reviewer_comment")),
    ]
    for label, value in fields:
        doc.add_paragraph(f"{label}: {value or ''}")


def generate_two_version_report(
    output_path: str | Path,
    analysis: dict[str, Any],
    suggestions: list[dict[str, Any]],
    reviewer_decisions: dict[str, Any] | None = None,
) -> Path:
    if Document is None:
        raise RuntimeError("python-docx is not installed. Install dependencies before generating the report.")
    path = Path(output_path)
    path.parent.mkdir(parents=True, exist_ok=True)
    reviewer_decisions = reviewer_decisions or {}
    resolved = analysis.get("resolved_pair", {})
    comparison = analysis.get("comparison", {})
    dependency = analysis.get("dependency", {})

    doc = Document()
    apply_business_brief_styles(doc)
    add_report_header_footer(doc)

    title = doc.add_paragraph()
    title.style = doc.styles["Title"]
    title.add_run("Two-Version Regulatory Impact Assessment")
    subtitle = doc.add_paragraph("AI-assisted controlled-document amendment evidence report")
    subtitle.alignment = WD_ALIGN_PARAGRAPH.LEFT
    subtitle.runs[0].font.color.rgb = RGBColor(71, 85, 105)
    subtitle.runs[0].font.size = Pt(12)
    doc.add_paragraph("Draft only - not approved. Human QA/RA confirmation is required before implementation.")

    doc.add_heading("1. Input Resolution", level=1)
    add_label_value(doc, "Regulation family", resolved.get("family_key", resolved.get("family", "")))
    add_label_value(
        doc,
        "Earlier version",
        f"{resolved.get('old_year', '')} | "
        f"{resolved.get('old_file_name') or resolved.get('old', {}).get('file_name') or resolved.get('old_file', '')}",
    )
    add_label_value(
        doc,
        "Later version",
        f"{resolved.get('latest_year', '')} | "
        f"{resolved.get('latest_file_name') or resolved.get('latest', {}).get('file_name') or resolved.get('latest_file', '')}",
    )
    add_label_value(doc, "Filename match", resolved.get("match_mode", ""))
    source = analysis.get("document_library", {})
    add_label_value(doc, "Controlled-document source", source.get("source_label", ""))
    add_label_value(doc, "Controlled-document source ID", source.get("source_id", ""))

    doc.add_heading("2. Regulation Change Evidence", level=1)
    add_label_value(doc, "Selected comparison method", comparison.get("selected_method", comparison.get("comparison_method", "")))
    add_label_value(doc, "Accepted substantive changes", len(comparison.get("accepted_changes", [])))
    add_label_value(doc, "Human-confirmation conflicts", len(comparison.get("conflicts", [])))
    for change in comparison.get("accepted_changes", [])[:100]:
        clause = str(change.get("latest_clause_id") or change.get("official_clause_id") or change.get("old_clause_id", ""))
        paragraph = doc.add_paragraph(style="List Bullet")
        paragraph.add_run(f"Clause {clause}: ").bold = True
        paragraph.add_run(change_summary(change))

    doc.add_heading("3. Recursive Affected-File Set", level=1)
    nodes = dependency.get("nodes", [])
    add_label_value(doc, "Affected controlled files", len(nodes))
    add_label_value(doc, "Unresolved Section 3 references", len(dependency.get("unresolved_references", [])))
    for node in nodes[:250]:
        paragraph = doc.add_paragraph(style="List Bullet")
        paragraph.add_run(f"{node.get('document_code', '')} | depth {node.get('depth', 0)} | ").bold = True
        path_value = node.get("relationship_path", "")
        paragraph.add_run(" -> ".join(str(value) for value in path_value) if isinstance(path_value, list) else str(path_value))

    doc.add_heading("4. Content-Based Amendment Suggestions", level=1)
    if not suggestions:
        doc.add_paragraph("No AI suggestion job results were available when this report was generated.")
    for result in suggestions:
        code = str(result.get("document_code", "Affected document"))
        doc.add_heading(code, level=2)
        add_label_value(doc, "Decision", result.get("decision", ""))
        add_label_value(doc, "Confidence", result.get("confidence", ""))
        add_label_value(doc, "Dependency path", result.get("relationship_path", ""))
        add_label_value(doc, "Reason", result.get("reason", ""))
        decision = reviewer_decisions.get(str(result.get("row_id", "")), {})
        add_label_value(doc, "QA/RA reviewer decision", decision.get("decision", "Pending"))
        add_label_value(doc, "QA/RA reviewer comment", decision.get("comment", ""))
        for item in result.get("suggestions", []):
            doc.add_heading(f"Section {item.get('section_id', '')}", level=3)
            add_label_value(doc, "Current text", item.get("current_text", ""))
            add_label_value(doc, "Proposed draft text", item.get("proposed_text", ""))
            add_label_value(doc, "Rationale", item.get("rationale", ""))
            add_label_value(doc, "Regulation evidence IDs", ", ".join(item.get("evidence_ids", [])))

    doc.add_heading("5. Limitations and Approval", level=1)
    for line in [
        "[ ] QA/RA confirmed the uploaded editions and regulatory source.",
        "[ ] QA/RA verified every cited regulation clause and controlled-document section.",
        "[ ] Any accepted amendment will follow the controlled document-change procedure.",
    ]:
        doc.add_paragraph(line)
    doc.add_paragraph(DISCLAIMER)
    doc.save(path)
    return path


def apply_business_brief_styles(doc: Any) -> None:
    section = doc.sections[0]
    section.page_width = Inches(8.5)
    section.page_height = Inches(11)
    section.top_margin = Inches(1)
    section.right_margin = Inches(1)
    section.bottom_margin = Inches(1)
    section.left_margin = Inches(1)
    section.header_distance = Inches(0.492)
    section.footer_distance = Inches(0.492)

    configure_style(doc.styles["Normal"], 11, "000000", 0, 6, 1.1)
    configure_style(doc.styles["Title"], 23, "0F172A", 0, 4, 1.0, bold=True)
    configure_style(doc.styles["Heading 1"], 16, "0F766E", 16, 8, 1.0, bold=True)
    configure_style(doc.styles["Heading 2"], 13, "0F766E", 12, 6, 1.0, bold=True)
    configure_style(doc.styles["Heading 3"], 12, "115E59", 8, 4, 1.0, bold=True)
    configure_style(doc.styles["List Bullet"], 11, "000000", 0, 8, 1.167)


def configure_style(style: Any, size: float, color: str, before: float, after: float, line: float, bold: bool = False) -> None:
    style.font.name = "Calibri"
    style._element.rPr.rFonts.set(qn("w:ascii"), "Calibri")
    style._element.rPr.rFonts.set(qn("w:hAnsi"), "Calibri")
    style.font.size = Pt(size)
    style.font.color.rgb = RGBColor.from_string(color)
    style.font.bold = bold
    style.paragraph_format.space_before = Pt(before)
    style.paragraph_format.space_after = Pt(after)
    style.paragraph_format.line_spacing = line


def add_report_header_footer(doc: Any) -> None:
    section = doc.sections[0]
    header = section.header.paragraphs[0]
    header.text = "QMS Regulatory Update Assistant | Draft Evidence Report"
    header.alignment = WD_ALIGN_PARAGRAPH.RIGHT
    for run in header.runs:
        run.font.name = "Calibri"
        run.font.size = Pt(8.5)
        run.font.color.rgb = RGBColor(100, 116, 139)
    footer = section.footer.paragraphs[0]
    footer.alignment = WD_ALIGN_PARAGRAPH.RIGHT
    run = footer.add_run("Page ")
    run.font.size = Pt(8.5)
    field = OxmlElement("w:fldSimple")
    field.set(qn("w:instr"), "PAGE")
    run._r.addnext(field)


def add_label_value(doc: Any, label: str, value: Any) -> None:
    paragraph = doc.add_paragraph()
    label_run = paragraph.add_run(f"{label}: ")
    label_run.bold = True
    paragraph.add_run(str(value or ""))


def change_summary(change: dict[str, Any]) -> str:
    for key in ["official_change_comment", "change_comment", "evidence_preview", "latest_clause_title"]:
        value = str(change.get(key, "")).strip()
        if value:
            return value
    units = change.get("added_requirement_units", []) or change.get("changed_requirement_units", [])
    return str(units[0]) if units else "Substantive paired change identified."
